eq(bbase.dtype,"float64","fmod/complex64(2, 1)/float64(1, 3)/C/out/float64/maskTrue/rawFalse,False: b backing: dtype")
cases=cases+1
end
end
chunk()
end
assert(cases==1428)
print("fmod109: "..cases.." cases; "..checks.." checks; max_error="..max_error.." max_relative_error="..max_relative_error)
